for _ in range(int(input())):
	(x, y) = map(int, input().split())
	temp = []
	m = 1
	while m * x <= y:
		temp.append(m * x)
		m = 2 * m + 1
	count = 0
	for i in range(len(temp) - 1, -1, -1):
		if temp[i] <= y:
			y -= temp[i]
			count += i + 2
	count -= 1
	if y != 0:
		print(-1)
	else:
		print(count)
